@-moz-document domain("discord.com") {
/* Fondo de pantalla */
  body {
    background: linear-gradient(to right, rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
                url("https://media.discordapp.net/attachments/1247698182872367136/1298840624497295473/IMG_20241022_215914.png?ex=67263bd8&is=6724ea58&hm=6a6887398c827fdad09bf2994c2770806cee751c38a84d55f5a9ba5133d36058&=&format=webp&quality=lossless&width=1103&height=600") 
                no-repeat center center fixed;
    background-size: cover; /* Cubre toda la pantalla */
    color: #ffffff; /* Color de texto blanco para contraste */
    font-family: Arial, sans-serif;
  }

  /* Ajustes para contenedores principales en Discord */
  .container-1giJp5, .content-98HsJk, .mainContent-20jcrP {
    background-color: rgba(255, 255, 255, 0.8); /* Fondo semi-transparente */
    padding: 20px;
    border-radius: 8px;
  }

  /* Color para encabezados */
  h1, h2, h3, h4, h5, h6 {
    color: #ffcc00; /* Color dorado para encabezados */
  }

  /* Enlaces */
  a {
    color: #66c2ff; /* Azul claro para enlaces */
    text-decoration: none;
  }

  a:hover {
    color: #ffffff;
    text-decoration: underline;
  }
  
  /* Botones */
  button, .btn {
    background-color: #ffcc00;
    color: #333;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
  }

  button:hover, .btn:hover {
    background-color: #ff9900;
  }
}
